class Solution {
  public long minimumCost(int[] nums, int[] cost, int k) {
    int n = nums.length;
    long[] P = new long[n + 1], C = new long[n + 1];
    for (int i = 0; i < n; i++) {
      P[i + 1] = P[i] + nums[i];
      C[i + 1] = C[i] + cost[i];
    }
    long INF = Long.MAX_VALUE / 4;
    long[] dp = new long[n + 1];
    java.util.Arrays.fill(dp, INF);
    dp[0] = 0;
    for (int r = 1; r <= n; r++) {
      for (int l = 0; l < r; l++) {
        long v = dp[l] + P[r] * (C[r] - C[l]) + (long) k * (C[n] - C[l]);
        if (v < dp[r]) dp[r] = v;
      }
    }
    return dp[n];
  }
}
